.zen-mode .note-evidence,
[data-zen="true"] .note-evidence {
  opacity: 0.75;
}

/* ── The note ──
   Full measure. In a 340px panel the reading column is scarce, so
   the body does not pay for the gutter the masthead spends. */
.desk-card__body {
  font-family: var(--font-serif);
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--color-ink-light);
}
.desk-card__body--clamped {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  overflow: hidden;
  cursor: pointer;
}
/* A run of monospaced detail — a URL, a raw citation string. */
.desk-card__detail {
