.site-select__option.is-active,
.site-select__option:hover {
  background: var(--color-paper-2);
  color: var(--color-ink);
}

.site-select__option.is-selected {
  color: var(--color-vermilion-2);
}

.site-select__check {
  color: var(--color-vermilion);
  font-family: var(--font-typewriter);
}

.site-select__option-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.12rem;
}

.site-select__option-copy > span {
  overflow-wrap: anywhere;
}

.site-select__option-copy small {
  color: var(--color-ink-muted);
  font-family: var(--font-serif);
  font-size: 0.6875rem;
  line-height: 1.35;
}

.mcp-connection-select {
  flex: 0 1 14rem;
  min-width: min(12rem, 100%);
}

/* A foot key. Small typewriter caps with a real hit area, so the
   actions stop reading as another sentence of the note. */
.card-key {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.2rem var(--card-key-inset);
  border: 0;
  border-radius: 2px;
  background: transparent;
  font-family: var(--font-typewriter);
  font-size: 0.6875rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  line-height: 1.3;
  color: var(--color-ink-muted);
  cursor: pointer;
  transition:
    color 0.16s ease,
    background 0.16s ease;
}
.card-key:hover:not(:disabled),
.card-key:focus-visible {
  color: var(--color-vermilion);
  background: color-mix(in srgb, var(--color-vermilion) 8%, transparent);
}
.card-key:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.card-key--go:hover:not(:disabled),
.card-key--go:focus-visible {
  color: var(--color-accent-green);
  background: color-mix(in srgb, var(--color-accent-green) 10%, transparent);
}
.card-key--on {
  color: var(--color-vermilion);
}
/* A key that destroys something. Reads quiet until you reach for it,
   then commits to vermilion — and says so before it acts. */
.card-key--danger:hover:not(:disabled),
.card-key--danger:focus-visible {
  color: var(--color-paper);
  background: var(--color-vermilion);
}
.card-key--arming {
  color: var(--color-paper);
  background: var(--color-vermilion);
}

/* ── Room notes ──
   Two kinds of note share one skeleton. A filed note is something the
   writer asked for: a sheet of paper with the editor's colour along its top
   edge and a stamped category. A note left in passing arrived on its own:
   no sheet, a rule down the margin, its kind said in italic rather than
   stamped. Both wear the same head, so a glance compares them line for line. */
.note-card {
  container-type: inline-size;
  gap: 0.6rem;
}
.note-card--filed {
  border: 1px solid
    color-mix(in srgb, var(--card-accent) 30%, var(--color-paper-3));
  border-radius: 2px;
  background: var(--color-paper);
  box-shadow:
    inset 0 3px 0 color-mix(in srgb, var(--card-accent) 80%, transparent),
    0 8px 16px -14px rgb(31 27 22 / 0.35);
  padding-top: calc(var(--card-pad-y) + 3px);
}
.note-card--passing {
  --card-pad-y: 0.65rem;
  border-left: 2px solid color-mix(in srgb, var(--card-accent) 75%, transparent);
  border-radius: 0;
  background: transparent;
  transition: background 0.18s ease;
}
.note-card--passing:hover,
.note-card--passing:focus-within {
  background: color-mix(in srgb, var(--card-accent) 5%, var(--color-paper));
}
.note-card--passing .desk-card__body {
  font-size: 0.84375rem;
}

/* The head. Three columns, all rows sized by their content. */
.note-card__head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    "mark who kind"
    "mark who tools";
  align-items: start;
  column-gap: 0.65rem;
  row-gap: 0.15rem;
  min-width: 0;
}
.note-card__head > .persona-portrait {
  grid-area: mark;
  align-self: center;
}
.note-card__who {
  grid-area: who;
  min-width: 0;
  align-self: center;
}
.note-card__name {
  margin: 0;
  font: 600 0.9375rem/1.25 var(--font-display);
  color: var(--color-ink);
  /* Two lines and an ellipsis: a long name grows the head but never
     takes it over. The full name is in the title and the open sheet. */
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  overflow-wrap: anywhere;
}
.note-card--passing .note-card__name {
  font-size: 0.875rem;
}
.note-card__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 0.45rem;
  margin: 0.15rem 0 0;
  font: 400 0.75rem/1.35 var(--font-sans);
  color: var(--color-ink-muted);
}
.note-card__role {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--color-ink-light);
}
.note-card__when {
  font-family: var(--font-typewriter);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  white-space: nowrap;
}
.note-card__role + .note-card__when::before {
  content: "·";
  margin-right: 0.45rem;
}
.note-card__kind {
  grid-area: kind;
  justify-self: end;
  max-width: 11rem;
  padding: 0.05rem 0.35rem;
  border: 1px solid color-mix(in srgb, var(--card-accent) 55%, transparent);
  border-radius: 2px;
  font-family: var(--font-typewriter);
  font-size: 0.625rem;
  letter-spacing: 0.12em;
  line-height: 1.5;
  text-transform: uppercase;
  text-align: right;
  color: color-mix(in srgb, var(--card-accent) 80%, var(--color-ink));
}
.note-card--passing .note-card__kind {
  padding: 0;
  border: 0;
  font: italic 400 0.8125rem/1.3 var(--font-serif);
  letter-spacing: 0;
  text-transform: none;
  color: var(--color-ink-muted);
}
.note-card__tools {
  grid-area: tools;
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 0.15rem;
}
.note-card__open {
  display: inline-grid;
  place-items: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 2px;
  color: var(--color-ink-muted);
  transition:
    color 0.15s ease,
    background 0.15s ease;
}
.note-card__open:hover,
.note-card__open:focus-visible {
  color: var(--color-ink);
  background: color-mix(in srgb, var(--card-accent) 12%, transparent);
}
.note-card__open:focus-visible {
  outline: 2px solid var(--color-vermilion);
  outline-offset: 1px;
}
/* A narrow column: the kind and the tools drop under the name, so the
   name keeps its measure instead of being squeezed to a word a line. */
@container (max-width: 23rem) {
  .note-card__head {
    grid-template-areas:
      "mark who who"
      "kind kind tools";
    row-gap: 0.45rem;
  }
  .note-card__kind {
}
.user-comment-card .persona-note__compose:only-child {
  margin-top: calc(-1 * var(--persona-note-rise));
  align-items: center;
}

/* A persona note wears the shared comment-card layout; the older
   stand-alone note card's padding and paper would frame it as a card
   inside a card. */
.persona-note-card.manuscript-comment-card,
.suggestion-card.manuscript-comment-card {
  padding: 0;
  background: var(--color-paper);
  border-color: var(--comment-color);
}

/* Persona note: two stacked boxes, the editor's engraving standing on the
   first. Face and --comment-color name the editor, so no text does. */
.twyne-card.manuscript-comment-card,
.twyne-card.manuscript-comment-card.is-in-margin {
  --persona-note-rise: 1.75rem;
  gap: 0.375rem;
  overflow: visible;
  padding-top: var(--persona-note-rise);
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.persona-note__note,
