import type posthog from "posthog-js";

export type PostHogClient = typeof posthog;
export const POSTHOG_LOAD_TIMEOUT_MS = 1500;

/** An optional SDK must never reject app work or wait indefinitely to load. */
export function createPostHogRuntime(
  load: () => Promise<PostHogClient>,
  initialize: (client: PostHogClient) => void,
  timeoutMs = POSTHOG_LOAD_TIMEOUT_MS,
) {
  let client: PostHogClient | null = null;
  let pending: Promise<PostHogClient | null> | null = null;
  let disabled = false;

  const disable = () => {
    disabled = true;
    client = null;
  };

  const get = (): Promise<PostHogClient | null> => {
    if (disabled) return Promise.resolve(null);
    if (pending) return pending;

    pending = new Promise((resolve) => {
      const timeout = setTimeout(() => {
        disable();
        resolve(null);
      }, timeoutMs);

      void Promise.resolve()
        .then(load)
        .then((loaded) => {
          if (disabled) return;
          initialize(loaded);
          client = loaded;
          resolve(loaded);
        })
        .catch(() => {
          disable();
          resolve(null);
        })
        .finally(() => clearTimeout(timeout));
    });

    return pending;
  };

  const run = (action: (client: PostHogClient) => void): void => {
    void get().then((loaded) => {
      if (!loaded || disabled) return;
      try {
        action(loaded);
      } catch {
        disable();
      }
    });
  };

  return { get, run, disable, peek: () => client };
}
import type { PostHogConfig } from "posthog-js";

/**
 * Keep this aligned with the current PostHog recommended defaults. The
 * explicit history setting below is intentional: a future defaults change
 * must never silently turn Qwik City navigation back into load-only tracking.
 */
export const POSTHOG_DEFAULTS_VERSION = "2026-05-30";

/** Skip the SDK entirely in Firefox, including config, flags, and assets. */
export function shouldLoadPostHog(userAgent: string): boolean {
  return !/\b(?:Firefox|FxiOS)\//i.test(userAgent);
}

interface PostHogInitOptions {
  host: string;
  capture: boolean;
  flagKeys: string[];
}

export function buildPostHogInitOptions({
  host,
  capture,
  flagKeys,
}: PostHogInitOptions): Partial<PostHogConfig> {
  return {
    api_host: host,
    defaults: POSTHOG_DEFAULTS_VERSION,
    autocapture: capture,
    capture_pageview: capture ? "history_change" : false,
    capture_pageleave: capture,
    disable_session_recording: !capture,
    opt_out_capturing_by_default: !capture,
    ...(capture ? { surveys: {} } : {}),
