import { chromium, firefox, expect, test } from "@playwright/test";

for (const browserName of ["chromium", "firefox"] as const) {
  test.describe(`Editorial board in ${browserName}`, () => {
    test("replies preserve focus in the card and full note", async ({
      baseURL,
    }) => {
      const browser = await { chromium, firefox }[browserName].launch();
      const context = await browser.newContext({
        baseURL,
        viewport: { width: 1280, height: 900 },
      });
      const page = await context.newPage();
      try {
        test.setTimeout(90_000);
        const errors: string[] = [];
        page.on("pageerror", (error) => errors.push(error.message));
        console.log(browserName, "loading editor");
        await page.goto("/editor/");
        console.log(browserName, "opening board");
        await page
          .getByRole("button", { name: "Toggle the editorial board panel" })
          .click();
        await expect(
          page.getByRole("button", { name: "✦ Get notes" }),
        ).toBeVisible();
        await page.evaluate(() =>
          window.dispatchEvent(
            new CustomEvent("twyne:background-room-notes", {
              detail: Array.from({ length: 19 }, (_, i) => ({
                noteId: `board-note-${i}`,
                personaId: "editor",
                personaName: "Focus fixture",
                personaColor: "#87523e",
                type: "suggestion",
                feedback:
                  "A local reply and layout fixture. Keep the map on the desk.",
                anchor: "The map remained on the desk.",
                timestamp: Date.now() + i,
                traceId: `fixture-trace-${i}`,
              })),
            }),
          ),
        );
        console.log(browserName, "checking replies");
        const card = page.locator(".board-card").first();
        await expect(card).toContainText("18 older");
        await card.getByRole("button", { name: "Reply", exact: true }).click();
        const input = card.getByRole("textbox", {
          name: "Reply to Focus fixture",
        });
        await input.focus();
        const original = await input.elementHandle();
        await input.pressSequentially("Typing keeps focus", { delay: 60 });
        await expect(input).toHaveValue("Typing keeps focus");
        await expect(input).toBeFocused();
        expect(await original!.evaluate((el) => el.isConnected)).toBe(true);
        await card
          .getByRole("button", {
            name: "Open the full note from Focus fixture",
          })
          .click();
        const dialog = page.locator("dialog.note-sheet[open]");
        const modalInput = dialog.getByRole("textbox", {
          name: "Reply to Focus fixture",
        });
        await expect(modalInput).toBeFocused();
        const originalModal = await modalInput.elementHandle();
        await modalInput.pressSequentially(" in the full note", { delay: 60 });
        await expect(modalInput).toHaveValue(
          "Typing keeps focus in the full note",
        );
        await expect(modalInput).toBeFocused();
        expect(await originalModal!.evaluate((el) => el.isConnected)).toBe(
          true,
        );
      } finally {
        await browser.close();
      }
    });
  });
}
