import { mutationGeneric, queryGeneric } from "convex/server";
import { ConvexError, v } from "convex/values";
import { now, requireDid, requireGatewaySecret } from "./lib";
import { releaseFunds, reserveFunds, settleFunds } from "./wallet";
import { orgContextValidator, requireOrgContext, reserveOrgFunds, settleOrgFunds } from "./orgBilling";
import { agentContextValidator, resolveDelegationAuthority } from "./agentDelegations";
import { requireRequestAuthority } from "./resourceAuthority";
import { ensureKeatingWelcomeGrant } from "./welcomeGrants";

/** Resolve existing liability without reserving, repricing, expiring or refunding it. */
export const lookup = queryGeneric({
  args: {
    serviceSecret: v.string(), did: v.string(), product: v.string(), feature: v.string(),
    model: v.string(), idempotencyKey: v.string(), requestHash: v.string(),
    orgContext: v.optional(orgContextValidator), agentContext: v.optional(agentContextValidator),
    sessionVersion: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    requireGatewaySecret(args.serviceSecret);
    if (args.orgContext && !args.agentContext) await requireOrgContext(ctx, { ...args, orgContext: args.orgContext });
    const account = await ctx.db.query("didAccounts").withIndex("by_did", q => q.eq("did", args.did)).unique();
    if (args.sessionVersion !== undefined && args.sessionVersion !== (account?.sessionVersion ?? 0)) throw new ConvexError("session_revoked");
    if (args.agentContext) await resolveDelegationAuthority(ctx, { ...args, agentContext: args.agentContext });
    const actorKey = args.agentContext ? `\u0000agent:${args.agentContext.agent_id}\u0000delegation:${args.agentContext.delegation_id}` : "";
    const idempotencyLookup = args.orgContext ? `org:${args.orgContext.org_id}\u0000${args.did}${actorKey}\u0000${args.idempotencyKey}` : `${args.did}${actorKey}\u0000${args.idempotencyKey}`;
    // Same exact-value match as begin: legacy retired lookups share the index range.
    const matches = await ctx.db.query("inferenceRequests").withIndex("by_idempotency_lookup", q => q.eq("idempotencyLookup", idempotencyLookup))
      .filter(q => q.eq(q.field("idempotencyLookup"), idempotencyLookup)).take(2);
    if (matches.length > 1) throw new ConvexError("IDEMPOTENCY_CONFLICT");
    const request = matches[0];
    if (!request) return null;
    if (request.did !== args.did || request.orgId !== args.orgContext?.org_id ||
      request.agentId !== args.agentContext?.agent_id || request.delegationId !== args.agentContext?.delegation_id ||
      request.model !== args.model || request.product !== args.product || request.feature !== args.feature || request.requestHash !== args.requestHash) {
      throw new ConvexError("IDEMPOTENCY_CONFLICT");
    }
    // Match begin's retry policy, leaving retirement and new credit allocation to that mutation.
    if (request.state === "expired" || (request.state === "failed" && (request.billedMicros ?? 0) === 0)) return null;
    return request;
  },
});

