import { expect, test } from "bun:test";
import { convexTest } from "convex-test";
import { makeFunctionReference } from "convex/server";
import schema from "../convex/schema";
import { ConvexProviderStore } from "../apps/gateway/src/convex-store";
import type { OpenBaoTransit } from "../apps/gateway/src/openbao";
import { OWNER_HISTORY_TABLES } from "../convex/providerErasure";

const secret = "async-media-accounting-test";
test("encrypted async jobs preserve the maximum reservation across expiry, ownership and duplicate completion", async () => {
  const previous = process.env.CONVEX_GATEWAY_SECRET; process.env.CONVEX_GATEWAY_SECRET = REDACTED;
  try {
    const t = convexTest(schema, {
      "../convex/_generated/server.js": () => import("../convex/_generated/server.js"),
      "../convex/billing.ts": () => import("../convex/billing"),
      "../convex/inference.ts": () => import("../convex/inference"),
      "../convex/gateway.ts": () => import("../convex/gateway"),
      "../convex/asyncMedia.ts": () => import("../convex/asyncMedia"),
      "../convex/maintenance.ts": () => import("../convex/maintenance"),
    });
    const did = "did:plc:async-media"; const now = Date.now();
    await t.run(ctx => ctx.db.insert("didAccounts", { did, pdsUrl: "https://pds.test", recoveryState: "active", createdAt: now, updatedAt: now }));
    await t.mutation(makeFunctionReference<"mutation">("billing:ingestCreemEvent"), { eventId: "async-fixture", objectId: "async-fixture", eventType: "checkout.completed", createdAt: now, payloadHash: "fixture", did, product: "twyne", plan: "twyne_credit_10", status: "paid" });
    const encrypted = new Map<string, { plaintext: string; context: string }>();
    const store = new ConvexProviderStore({
      convexUrl: "https://example.convex.cloud", gatewaySecret: secret, paddleGrantPrograms: {},
      convexClient: { query: (ref: any, args: any) => t.query(ref, args), mutation: (ref: any, args: any) => t.mutation(ref, args) },
      transit: {
        encrypt: async (plaintext: string, context: string) => { const ciphertext = `encrypted-${crypto.randomUUID()}`; encrypted.set(ciphertext, { plaintext, context }); return { ciphertext, keyVersion: "1", aadHash: "fixture" }; },
        decrypt: async (ciphertext: string, context: string) => { const item = encrypted.get(ciphertext)!; expect(item.context).toBe(context); return item.plaintext; },
      } as unknown as OpenBaoTransit,
    });
    const id = "vid_durable_test";
    await store.reserve({ accountId: did, product: "interleave", requestId: id, idempotencyKey: id, requestHash: "fixture", feature: "vid", alias: "vid", pricingVersion: "test", maxCostMicrousd: 1000 });
    expect(await store.claimMeteredDispatch({ requestId: id, accountId: did, product: "interleave" })).toBe(true);
    expect(await store.claimMeteredDispatch({ requestId: id, accountId: did, product: "interleave" })).toBe(false);
    await store.markAccepted({ requestId: id, upstreamRequestId: "fal-test" });
    const job = { id, product: "interleave", request_hash: "fixture", status: "queued", internal: { statusUrl: "https://queue.fal.run/fal-ai/model/requests/job/status" } };
    await store.putAsyncJob({ accountId: did, job, terminal: false });
    expect(await store.getAsyncJob({ accountId: did, jobId: id })).toEqual(job);
    expect(await store.getAsyncJob({ accountId: "did:plc:mallory", jobId: id })).toBeNull();
    expect(await store.getResponse({ accountId: did, responseId: id })).toBeNull();
    await expect(store.putAsyncJob({ accountId: did, job: { ...job, product: "keating" }, terminal: false })).rejects.toThrow("ASYNC_JOB_REQUEST_INVALID");
    await t.run(async ctx => { const row = await ctx.db.query("reservations").first(); await ctx.db.patch(row!._id, { expiresAt: Date.now() - 1 }); });
    await t.mutation(makeFunctionReference<"mutation">("maintenance:sweepReservations"), {});
    expect(await t.run(ctx => ctx.db.query("reservations").first())).toMatchObject({ state: "open", estimatedMicros: 1000 });
    await t.run(async ctx => { const row = await ctx.db.query("asyncMediaJobs").first(); await ctx.db.patch(row!._id, { nextPollAt: Date.now() - 1 }); });
    expect(await store.listAsyncJobs()).toEqual([{ accountId: did, job }]);
    const final = { id, product: "interleave", status: "succeeded", video_url: "https://cdn.fal.media/video.mp4" };
    await store.settleWithResponse({ requestId: id, accountId: did, actualCostMicrousd: 500, response: final });
    await store.settleWithResponse({ requestId: id, accountId: did, actualCostMicrousd: 500, response: final });
    await store.putAsyncJob({ accountId: did, job: { ...job, status: "succeeded" }, terminal: true });
    await store.putAsyncJob({ accountId: did, job, terminal: false });
    expect(await store.getAsyncJob({ accountId: did, jobId: id })).toMatchObject({ status: "succeeded" });
    expect(await store.listAsyncJobs()).toEqual([]);
    expect(await store.getResponse({ accountId: did, responseId: id })).toEqual(final);
    const lots = await t.run(ctx => ctx.db.query("grantLots").collect()); expect(lots[0]!.remainingMicros).toBe(10_000_000 - 500);
    expect(OWNER_HISTORY_TABLES).toContain("asyncMediaJobs");
  } finally { if (previous === undefined) delete process.env.CONVEX_GATEWAY_SECRET; else process.env.CONVEX_GATEWAY_SECRET = REDACTED; }
});
