import { ConvexError } from "convex/values";
import type { GenericMutationCtx, GenericQueryCtx } from "convex/server";
import type { DataModel, Doc } from "./_generated/dataModel";
import { requireOrgContext } from "./orgBilling";
import { resolveDelegationAuthority } from "./agentDelegations";
import { accountDeleted } from "./accountDeletion";

/** Revalidate new paid steps. In-flight completion never calls this gate. */
export async function requireRequestAuthority(ctx: GenericMutationCtx<DataModel> | GenericQueryCtx<DataModel>, request: Doc<"inferenceRequests">) {
  const account = await ctx.db.query("didAccounts").withIndex("by_did", q => q.eq("did", request.did)).unique();
  if (await accountDeleted(ctx, request.did) || (account && account.recoveryState !== "active")
    || (!account && (request.orgId || request.agentId))) throw new ConvexError("account_deleted");
  const snapshot = request.authorization;
  if (snapshot && snapshot.sessionVersion !== (account?.sessionVersion ?? 0)) throw new ConvexError("session_revoked");
  if (request.orgId && !request.agentId) {
    if (!snapshot?.orgContext) throw new ConvexError("org_context_stale");
    await requireOrgContext(ctx, { did: request.did, product: request.product, orgContext: snapshot.orgContext });
  }
  if (request.agentId) {
    if (!snapshot?.agentContext) throw new ConvexError("delegation_revoked");
    await resolveDelegationAuthority(ctx, { did: request.did, product: request.product, agentContext: snapshot.agentContext, orgContext: snapshot.orgContext });
  }
}
