/** Revalidate new paid steps. In-flight completion never calls this gate. */
export async function requireRequestAuthority(ctx: GenericMutationCtx<DataModel> | GenericQueryCtx<DataModel>, request: Doc<"inferenceRequests">) {
  const account = await ctx.db.query("didAccounts").withIndex("by_did", q => q.eq("did", request.did)).unique();
