  const snapshot = request.authorization;
  if (snapshot && snapshot.sessionVersion !== (account?.sessionVersion ?? 0)) throw new ConvexError("session_revoked");
  if (request.orgId && !request.agentId) {
    if (!snapshot?.orgContext) throw new ConvexError("org_context_stale");
    await requireOrgContext(ctx, { did: request.did, product: request.product, orgContext: snapshot.orgContext });
  }
  if (request.agentId) {
    if (!snapshot?.agentContext) throw new ConvexError("delegation_revoked");
    await resolveDelegationAuthority(ctx, { did: request.did, product: request.product, agentContext: snapshot.agentContext, orgContext: snapshot.orgContext });
  }
}
