import { expect, test } from "bun:test";
import { convexTest } from "convex-test";
import schema from "../convex/schema";
import { ConvexProviderStore } from "../apps/gateway/src/convex-store";
import type { OpenBaoTransit } from "../apps/gateway/src/openbao";

const did = "did:plc:speech-dispatch-fixture";
const secret = "speech-dispatch-test-secret";

async function fixture(run: (value: Awaited<ReturnType<typeof setup>>) => Promise<void>) {
  const previous = process.env.CONVEX_GATEWAY_SECRET;
  process.env.CONVEX_GATEWAY_SECRET = REDACTED;
  try { await run(await setup()); } finally {
    if (previous === undefined) delete process.env.CONVEX_GATEWAY_SECRET;
    else process.env.CONVEX_GATEWAY_SECRET = REDACTED;
  }
}

async function setup() {
  const t = convexTest(schema, {
    "../convex/_generated/server.js": () => import("../convex/_generated/server.js"),
    "../convex/inference.ts": () => import("../convex/inference"),
    "../convex/asyncMedia.ts": () => import("../convex/asyncMedia"),
  });
  const account = await t.run(async ctx => {
    const account = await ctx.db.insert("didAccounts", { did, pdsUrl: "https://pds.test", recoveryState: "active", sessionVersion: 0, createdAt: 0, updatedAt: 0 });
    await ctx.db.insert("wallets", { did, currency: "USD_MICROS", balanceMicros: 10000, reservedMicros: 0, debtMicros: 0, updatedAt: 0 });
    await ctx.db.insert("walletEntries", { did, kind: "deposit", amountMicros: 10000, idempotencyKey: "fixture-deposit", createdAt: 0 });
    return account;
  });
  const store = new ConvexProviderStore({
    convexUrl: "https://fixture.convex.cloud", gatewaySecret: secret, paddleGrantPrograms: {}, transit: {} as OpenBaoTransit,
    convexClient: { query: (ref: any, args: any) => t.query(ref, args), mutation: (ref: any, args: any) => t.mutation(ref, args) },
  });
  const reserve = (requestId: string, feature = "speech") => store.reserve({ requestId, accountId: did, product: "twyne", feature, alias: "speech-eleven-v4", idempotencyKey: requestId, requestHash: requestId, maxCostMicrousd: 100, pricingVersion: "test", sessionVersion: 0 });
  const claim = (requestId: string, accountId = did, product = "twyne") => store.claimMeteredDispatch({ requestId, accountId, product });
  return { t, account, reserve, claim };
}

