  const request = await f.t.run(ctx => ctx.db.query("inferenceRequests").withIndex("by_request", q => q.eq("requestId", "speech-fixture")).unique());
  expect(request!.state).toBe("running");
}));

test("speech dispatch still revalidates the reservation's session authority", () => fixture(async f => {
  await f.reserve("revoked-speech");
