}));

test("the media dispatch gate still rejects unrelated request types", () => fixture(async f => {
  await f.reserve("unrelated-chat", "chat");
  await expect(f.claim("unrelated-chat")).rejects.toThrow("ASYNC_JOB_REQUEST_INVALID");
}));

